// Generated by VoltForge AI
// Board: ESP32_S2
const int pirPin = 2;
const int buzzerPin = 8;
void setup() {
  Serial.begin(115200);
  pinMode(pirPin, INPUT);
  pinMode(buzzerPin, OUTPUT);
}
void loop() {
  int motion = digitalRead(pirPin);
  if (motion == HIGH) {
    Serial.println("MOTION DETECTED");
    tone(buzzerPin, 1000, 200);
  }
  delay(500);
}

// Generated by VoltForge AI
